function check([operations, args], actual, expected) {
  const [n, blacklist] = args[0];
  if (!Array.isArray(actual) || actual.length !== operations.length || actual[0] !== null) return false;
  const banned = new Set(blacklist);
  const sorted = [...blacklist].sort((a, b) => a - b);
  const allowed = n - blacklist.length;
  // rank(v) = how many allowed integers are smaller than v, so a fair pick has a uniform rank in [0, allowed).
  const rank = (v) => {
    let lo = 0, hi = sorted.length;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (sorted[mid] < v) lo = mid + 1; else hi = mid; }
    return v - lo;
  };
  const counts = new Map();
  const buckets = Math.min(allowed, 20);
  const filled = new Array(buckets).fill(0);
  for (let i = 1; i < actual.length; i++) {
    const value = actual[i];
    if (!Number.isInteger(value) || value < 0 || value >= n || banned.has(value)) return false;
    counts.set(value, (counts.get(value) ?? 0) + 1);
    filled[Math.floor(rank(value) * buckets / allowed)]++;
  }
  const calls = actual.length - 1;
  // A count of a fair choice with probability p over n tries stays within 5.5 standard deviations (+3 slack).
  const fair = (seen, tries, p) => Math.abs(seen - tries * p) <= 5.5 * Math.sqrt(tries * p * (1 - p)) + 3;
  // No single value may come up much more often than 1 / allowed predicts.
  for (const seen of counts.values()) if (!fair(seen, calls, 1 / allowed)) return false;
  // Ranks split into equal buckets; each bucket gets about its share, and a chi-square adds power.
  let chi = 0, cells = 0;
  for (let b = 0; b < buckets; b++) {
    // Bucket b holds the ranks r with floor(r * buckets / allowed) === b.
    const p = (Math.ceil((b + 1) * allowed / buckets) - Math.ceil(b * allowed / buckets)) / allowed;
    if (!fair(filled[b], calls, p)) return false;
    const mean = calls * p;
    if (mean >= 5) {
      chi += (filled[b] - mean) ** 2 / mean;
      cells++;
    }
  }
  if (cells > 1 && chi > cells + 6 * Math.sqrt(2 * cells) + 8) return false;
  return true;
}

