function validate([operations, args]) {
  if (!Array.isArray(operations) || operations[0] !== 'Solution' || !Array.isArray(args) || args.length !== operations.length) return 'Start with "Solution" and give one argument list per operation.';
  if (!Array.isArray(args[0]) || args[0].length !== 2 || !Array.isArray(args[0][1])) return 'The constructor takes n and blacklist.';
  const [n, blacklist] = args[0];
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is between 1 and 10^9.';
  if (blacklist.length > 2000) return 'blacklist holds at most 2,000 values here.';
  if (blacklist.length > n - 1) return 'At least one integer from 0 to n - 1 must stay allowed.';
  if (blacklist.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each blacklisted value is between 0 and n - 1.';
  if (new Set(blacklist).size !== blacklist.length) return 'The blacklisted values must be distinct.';
  if (operations.length - 1 > 20000) return 'pick is called at most 2 * 10^4 times.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'pick' || !Array.isArray(args[i]) || args[i].length !== 0) return 'After the constructor, only pick() is called, with no arguments.';
  }
  return null;
}

