class Solution {
  constructor(n, blacklist) {
    this.size = n - blacklist.length;
    this.remap = new Map();
    const banned = new Set(blacklist);
    let last = n - 1;
    for (const value of blacklist) {
      if (value >= this.size) continue;
      while (banned.has(last)) last--;
      this.remap.set(value, last);
      last--;
    }
  }

  pick() {
    const index = Math.floor(Math.random() * this.size);
    if (this.remap.has(index)) return this.remap.get(index);
    return index;
  }
}

