class Solution {
  constructor(n, blacklist) {
    this.n = n;
    this.banned = new Set(blacklist);
  }
  pick() {
    // Rejection sampling: draw from the whole range until the value is allowed.
    for (;;) {
      const value = Math.floor(Math.random() * this.n);
      if (!this.banned.has(value)) return value;
    }
  }
}

