function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const style = pick(3);
  let n, count;
  if (!large) {
    n = 1 + pick(12);
    count = pick(n);
  } else if (style === 0) {
    // A huge range with a full blacklist spread over it, plus a block at the top.
    n = 1000000000 - pick(1000);
    count = 2000;
  } else if (style === 1) {
    // Almost everything is banned, so only a few values remain.
    n = 2001 + pick(30);
    count = 2000;
  } else {
    n = 2000 + pick(4000);
    count = Math.min(n - 1, 1000 + pick(1001));
  }
  const chosen = new Set();
  if (large && style === 0) for (let v = n - 1; chosen.size < 200; v--) if (rand() < 0.7) chosen.add(v);
  if (n <= 3 * count + 10) {
    // Dense: shuffle the whole range and keep a prefix.
    const all = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [all[i], all[j]] = [all[j], all[i]]; }
    for (let i = 0; chosen.size < count; i++) chosen.add(all[i]);
  } else {
    const low = large && style === 2 && rand() < 0.5;
    while (chosen.size < count) chosen.add(low ? pick(Math.ceil(n / 2)) : pick(n));
  }
  const blacklist = [...chosen];
  for (let i = blacklist.length - 1; i > 0; i--) { const j = pick(i + 1); [blacklist[i], blacklist[j]] = [blacklist[j], blacklist[i]]; }
  const calls = large ? 499 : 1 + pick(200);
  return [["Solution", ...Array(calls).fill("pick")], [[n, blacklist], ...Array.from({ length: calls }, () => [])]];
}
